class BowlingGame:
    def __init__(self):
        self.rolls = []
        self._frames = []
        self._current = []
        self._game_over = False

    def roll(self, pins):
        if self._game_over:
            raise Exception("Cannot roll after the game has ended")
        if not 0 <= pins <= 10:
            raise Exception("A roll must knock down between 0 and 10 pins")

        self._validate(pins)

        self.rolls.append(pins)
        self._current.append(pins)
        if self._frame_complete():
            self._frames.append(self._current)
            self._current = []
            if len(self._frames) == 10:
                self._game_over = True

    def score(self):
        if len(self._frames) < 10:
            raise Exception("Cannot score an incomplete game")

        rolls = self.rolls
        total = 0
        i = 0
        for frame in range(10):
            if frame < 9:
                if rolls[i] == 10:
                    total += 10 + rolls[i + 1] + rolls[i + 2]
                    i += 1
                elif rolls[i] + rolls[i + 1] == 10:
                    total += 10 + rolls[i + 2]
                    i += 2
                else:
                    total += rolls[i] + rolls[i + 1]
                    i += 2
            else:
                total += sum(rolls[i:])
        return total

    def _validate(self, pins):
        current = self._current
        if len(self._frames) < 9:
            if len(current) == 1 and current[0] < 10 and current[0] + pins > 10:
                raise Exception("Two rolls in a frame cannot score more than 10 points")
        else:
            if len(current) == 1:
                if current[0] < 10 and current[0] + pins > 10:
                    raise Exception("Two rolls in a frame cannot score more than 10 points")
            elif len(current) == 2:
                if current[0] == 10 and current[1] < 10 and current[1] + pins > 10:
                    raise Exception("Two bonus rolls cannot score more than 10 points")

    def _frame_complete(self):
        current = self._current
        if len(current) == 1:
            return current[0] == 10 and len(self._frames) < 9
        if len(self._frames) < 9:
            return len(current) == 2
        if len(current) == 2:
            return current[0] < 10 and current[0] + current[1] < 10
        return len(current) == 3

